// The extension's icons in public/icons, all copied from the brand kit
// (brand/png, generated by brand/scripts/build.mjs, the one place the design
// lives):
// - icon-{16,32,48,128}.png and icon-on-dark-*: for the extensions page and
//   the stores, Onyx and its Paper twin for dark surfaces. Up to 48 px they
//   are the Onyx glass design (a solid arrow), 128 the pixel arrow.
// - toolbar-{16,24,32}.png and toolbar-on-dark-*: the toolbar button, the
//   Onyx glass design at each size. The brand's gapped pixel arrow breaks up
//   into a grid of dots there. The dark tile with its light rim holds on light
//   and dark toolbars alike, so both variants are the same image; the theme
//   swap (wxt.config.ts, lib/platform.ts) stays so they can differ again.
// `--check` fails when any file is stale instead of writing it.
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";

const SIZES = [16, 32, 48, 128];
const VARIANTS = ["icon", "icon-on-dark"];
const TOOLBAR_SIZES = [16, 24, 32];
const brand = new URL("../../../brand/png/", import.meta.url);
const out = new URL("../public/icons/", import.meta.url);
const check = process.argv.includes("--check");

mkdirSync(out, { recursive: true });
const stale = [];
function put(name, data) {
  const target = new URL(name, out);
  if (existsSync(target) && readFileSync(target).equals(data)) return;
  if (check) stale.push(name);
  else writeFileSync(target, data);
}
const brandPng = (name) => readFileSync(new URL(name, brand));

for (const variant of VARIANTS) {
  for (const size of SIZES) {
    const name = `${variant}-${size}.png`;
    put(name, brandPng(name));
  }
}
for (const size of TOOLBAR_SIZES) {
  const onyx = brandPng(`icon-${size}.png`);
  put(`toolbar-${size}.png`, onyx);
  put(`toolbar-on-dark-${size}.png`, onyx);
}

if (stale.length > 0) {
  console.error(
    `public/icons is stale (${stale.join(", ")}): run pnpm --filter @boltget/extension icons`,
  );
  process.exit(1);
}
